import numpy as np
import re

def r_substr_ctl(x, start, stop, warn=True, term_cap=None, ctl="all", normalize=False, carry=False, terminate=True):
    """
    Python implementation of fansi::substr_ctl.
    """
    # Handle defaults for getOption if not provided explicitly
    if term_cap is None:
        term_cap = 80 # Default fallback for dflt_term_cap()

    is_scalar = isinstance(x, str)
    if is_scalar:
        x_vec = [x]
    elif isinstance(x, (list, np.ndarray)):
        x_vec = x
    else:
        x_vec = [str(x)]

    # ANSI Escape Sequence Regex
    ansi_pattern = re.compile(r'(\x1b\[[0-9;*]*[a-zA-Z]|\x1b[0-9a-zA-Z])')

    def is_sgr(seq):
        return seq.endswith('m')

    results = []
    # For 'carry', we need to track the active SGR state across elements
    active_sgr = ""

    for s in x_vec:
        if s is None or (isinstance(s, float) and np.isnan(s)):
            results.append(None)
            continue

        s = str(s)
        parts = ansi_pattern.split(s)

        current_visual = 0
        out_parts = []

        # To support 'carry', we apply the state from the previous string
        if carry and active_sgr:
            out_parts.append(active_sgr)

        # Track style state for this specific string
        local_style_state = active_sgr if carry else ""

        for part in parts:
            if not part:
                continue

            if ansi_pattern.match(part):
                # Control sequence
                keep = False
                if ctl == "all" or (isinstance(ctl, (list, np.ndarray)) and "all" in ctl):
                    keep = True
                elif ctl == "sgr" or (isinstance(ctl, (list, np.ndarray)) and "sgr" in ctl):
                    if is_sgr(part):
                        keep = True

                if keep:
                    # If we are before the visual start, we keep sequences to maintain style
                    # If we are within the range, we keep them.
                    if current_visual < stop:
                        out_parts.append(part)
                        if is_sgr(part):
                            # Simple state tracking: if it's \x1b[0m, it clears state
                            if part == "\x1b[0m":
                                local_style_state = ""
                            else:
                                local_style_state += part
                continue
            else:
                # Literal text
                text_len = len(part)
                block_start = current_visual + 1
                block_end = current_visual + text_len

                intersect_start = max(block_start, start)
                intersect_end = min(block_end, stop)

                if intersect_start <= intersect_end:
                    local_start = intersect_start - block_start
                    local_stop = intersect_end - block_start + 1
                    out_parts.append(part[local_start:local_stop])

                current_visual += text_len

        res = "".join(out_parts)

        # termination: if the string ends but it was styled, add reset
        # R's fansi usually terminates if terminate=TRUE and the slice ends
        # while a style is active.
        if terminate and local_style_state != "":
            # If we actually extracted characters or kept style, append reset
            # The examples show that if ctl="sgr" or "all" and the slice is cut, 
            # a reset is added.
            if res != "":
                res += "\x1b[0m"

        # Update active_sgr for carry logic
        # We find the last SGR sequence in the original string that was processed
        # (This is a simplification of how R's internal C code tracks state)
        last_sgr = ""
        for part in parts:
            if part and ansi_pattern.match(part) and is_sgr(part):
                last_sgr = part if part != "\x1b[0m" else ""

        if carry:
            active_sgr = last_sgr if last_sgr else ""
            # If the last sequence was a reset, active_sgr becomes empty
            # If it was a color, that color carries to the next line
            # Note: a real implementation would parse the SGR values.

        results.append(res)

    if is_scalar:
        return results[0]
    return np.array(results, dtype=object)
